import { Test } from 'ts-toolbelt'
import { Record } from '../Record'
import { Table, StringColumn, ReferenceColumn } from '../../db'

const MyTableSchema = Table({
    name: 'x_yz',
    schema: {
        test: StringColumn({}),
    },
})

const WrongTableSchema = Table({
    name: 'x_zz',
    schema: {
        test: StringColumn({}),
    },
})

const ReferenceTableSchema = Table({
    name: 'x_ref',
    schema: {
        ref: ReferenceColumn({
            referenceTable: 'x_yz',
        }),
    },
})

declare global {
    namespace Now {
        namespace Internal {
            namespace TableSchemas {
                interface MyTable2 extends Helper<typeof MyTableSchema> {}
                interface WrongTable extends Helper<typeof WrongTableSchema> {}
                interface ReferenceTable extends Helper<typeof ReferenceTableSchema> {}
            }

            interface Tables {
                x_yz: Table<TableSchemas.MyTable2>
                x_zz: Table<TableSchemas.WrongTable>
                x_ref: Table<TableSchemas.ReferenceTable>
            }
        }
    }
}

const MyRecord = Record({
    table: 'x_yz',
    $id: 1,
    data: {
        test: '123',
    },
})

const WrongRecord = Record({
    table: 'x_zz',
    $id: 2,
    data: {},
})

const ReferenceRecord = Record({
    table: 'x_ref',
    $id: 3,
    data: {
        ref: MyRecord,
    },
})

Record({
    table: 'x_ref',
    $id: 4,
    data: {
        // @ts-expect-error Reference a record on the wrong table
        ref: WrongRecord,
    },
})

Test.checks([
    Test.check<typeof MyRecord.table, 'x_yz', Test.Pass>(),
    Test.check<typeof WrongRecord.table, 'x_zz', Test.Pass>(),
    Test.check<typeof ReferenceRecord.table, 'x_ref', Test.Pass>(),
    Test.check<
        NonNullable<
            Exclude<
                NonNullable<NonNullable<Record<'x_ref'>['data']>['ref']>,
                Now.Internal.ExplicitKey | Now.Internal.TableBrand<string> | string
            >['table']
        >,
        'x_yz',
        Test.Pass
    >(),
])
